use std::io::{self, BufRead, Write};

type Link = Option<Box<Node>>;
struct Node {
    k: i64,
    l: Link,
    r: Link,
}

fn insert(t: &mut Link, k: i64) -> bool {
    match t {
        None => {
            *t = Some(Box::new(Node { k, l: None, r: None }));
            true
        }
        Some(n) => {
            if k < n.k {
                insert(&mut n.l, k)
            } else if k > n.k {
                insert(&mut n.r, k)
            } else {
                false
            }
        }
    }
}

fn contains(t: &Link, k: i64) -> bool {
    let mut cur = t;
    while let Some(n) = cur {
        if k == n.k {
            return true;
        }
        cur = if k < n.k { &n.l } else { &n.r };
    }
    false
}

fn take_min(t: &mut Link) -> i64 {
    if t.as_ref().unwrap().l.is_some() {
        take_min(&mut t.as_mut().unwrap().l)
    } else {
        let n = t.take().unwrap();
        *t = n.r;
        n.k
    }
}

fn delete(t: &mut Link, k: i64) -> bool {
    match t {
        None => false,
        Some(n) => {
            if k < n.k {
                delete(&mut n.l, k)
            } else if k > n.k {
                delete(&mut n.r, k)
            } else {
                if n.l.is_none() {
                    let r = n.r.take();
                    *t = r;
                } else if n.r.is_none() {
                    let l = n.l.take();
                    *t = l;
                } else {
                    n.k = take_min(&mut n.r);
                }
                true
            }
        }
    }
}

fn inorder(t: &Link, out: &mut Vec<String>) {
    if let Some(n) = t {
        inorder(&n.l, out);
        out.push(n.k.to_string());
        inorder(&n.r, out);
    }
}

fn height(t: &Link) -> usize {
    match t {
        None => 0,
        Some(n) => 1 + height(&n.l).max(height(&n.r)),
    }
}

fn main() {
    let stdin = io::stdin();
    let mut o = io::stdout().lock();
    let mut t: Link = None;
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let mut p = line.split_whitespace();
        let cmd = match p.next() {
            Some(c) => c,
            None => continue,
        };
        let x: i64 = p.next().and_then(|s| s.parse().ok()).unwrap_or(0);
        match cmd {
            "insert" => {
                writeln!(o, "{}", if insert(&mut t, x) { "ok" } else { "dup" }).unwrap()
            }
            "contains" => writeln!(o, "{}", if contains(&t, x) { "yes" } else { "no" }).unwrap(),
            "delete" => {
                writeln!(o, "{}", if delete(&mut t, x) { "ok" } else { "missing" }).unwrap()
            }
            "inorder" => {
                let mut v = Vec::new();
                inorder(&t, &mut v);
                if v.is_empty() {
                    writeln!(o, "<empty>").unwrap();
                } else {
                    writeln!(o, "{}", v.join(" ")).unwrap();
                }
            }
            "height" => writeln!(o, "{}", height(&t)).unwrap(),
            "min" | "max" => {
                let mut cur = &t;
                if cur.is_none() {
                    writeln!(o, "empty").unwrap();
                } else {
                    let mut last = 0;
                    while let Some(n) = cur {
                        last = n.k;
                        cur = if cmd == "min" { &n.l } else { &n.r };
                    }
                    writeln!(o, "{}", last).unwrap();
                }
            }
            _ => {}
        }
    }
}

